def djssSimplus(u, graph2):
    p = {}
    d = {}
    path = []
    while u in graph2:
        d[u] = 0
        p[u] = None
        stack = [u]
        while stack:
            u = stack.pop()
            path.append((u, d[u]))
            if v in graph2 and v not in d:
                d[v] = d[u] + graph2[u][v]
                p[v] = u
                stack.append(v)
            elif v in d and u in graph2 and v not in graph2.get(u):
                d[v] = d[u] + graph2[u][v]
                p[v] = u
                stack.append(v)

            path = [(p[u], d[u]) if u != s else (u, d[u]) for u, d in reversed(path) if d == min(d2)]
            if t in p:
                path.append((t, d[t]))
            return path
return djssSimplus(s, adj)

