def dijkstra(q: list[int]):
    dist = [10e5 for _ in range(n)]
    dist[q[0]] = 0

    while q:
        dq = []

        for i in q:
            for neighbor, weight in graph[i]:
                if dist[i] + weight < dist[neighbor]:
                    dist[neighbor] = dist[i] + weight
                    dq.append(neighbor)

        q = dq

    return dist

