class Node:
    def __init__(self, state, parent=None, cost=0):
        self.state = state
        self.parent = parent
        self.cost = cost
        self.known = set()

    def __eq__(self, other):
        return self.state == other.state

    def __hash__(self):
        return hash(self.state)

    def __lt__(self, other):
        return self.cost < other.cost

    def __gt__(self, other):
        return self.cost > other.cost

    def __ne__(self, other):
        return not self.__eq__(other)

    def direction(self, node):
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        dx, dy = self.state[0] - node.state[0], self.state[1] - node.state[1]
        for dx, dy in directions:
            if dx == dx and dy == dy:
                return dx, dy
        return None

def neighbors(node):
    x, y = node.state[0], node.state[1]

    def check_valid(x_, y_):
        if x_ < 0 or x_ >= len(grid) or y_ < 0 or y_ >= len(grid[0]):
            return False
        if '#' == grid[x_][y_]:
            return False
        if node.known.__contains__((x_, y_)):
            return False
        return True

    neighbors_ = []
    for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        x_, y_ = x + dx, y + dy
        if check_valid(x_, y_):
            neighbors_.append(Node(state=(x_, y_), parent=node, cost=dx ** 2 + dy ** 2))
    return neighbors_

def reconstruct_path(node):
    path = []
    while node:
        path.append(node.state)
        node = node.parent
    return path[::-1]

