"""Given a grid with # = wall and . = free space, and a start and goal location, recursively find a path from start to goal. If there is no path, return an empty list. If there are multiple paths, any one is acceptable."""

def explore(start: tuple[int, int], goal: tuple[int, int], explored: dict[tuple[int, int], list[tuple[int, int]]] = {}, directions: list[str] = [">", "<", "v", "^"], path: list[tuple[int, int]] = []) -> list[tuple[int, int]]:
    if start == goal: return (path + [start])

    if start in explored: return explored[start]

    r, c = start
    areas = [">", "<", "v", "^"]
    if r > 0: areas[areas.index("^")] = "."
    if r < len(grid) - 1: areas[areas.index("v")] = "."
    if c > 0: areas[areas.index(">")] = "."
    if c < len(grid[0]) - 1: areas[areas.index("<")] = "."
    explored[start] = []
    for area in areas:
        if area == ".": continue
        if area == ">": adj = (r, c + 1)
        elif area == "<": adj = (r, c - 1)
        elif area == "v": adj = (r + 1, c)
        else: adj = (r - 1, c)
        explored[start] += (explore(adj, goal, explored, areas[:areas.index(area)] + areas[areas.index(area) + 1:], path + [start]))
    return explored[start]

