def route(grid: list[str], path: list[tuple[int, int]], visited: set[tuple[int, int]]) -> list[tuple[tuple[int, int], set[tuple[int, int]]]]:
    """
    Given a path, find all paths to the goal that use the last cell in the path.
    """
    row, col = path[-1]
    if col > 0 and grid[row][col - 1] == '.' and (row, col - 1) not in visited:
        yield path + [(row, col - 1)], {*(visited - {(row, col)}), (row, col - 1)}
    if col < len(grid[0]) - 1 and grid[row][col + 1] == '.' and (row, col + 1) not in visited:
        yield path + [(row, col + 1)], {*(visited - {(row, col)}), (row, col + 1)}
    if row > 0 and grid[row - 1][col] == '.' and (row - 1, col) not in visited:
        yield path + [(row - 1, col)], {*(visited - {(row, col)}), (row - 1, col)}
    if row < len(grid) - 1 and grid[row + 1][col] == '.' and (row + 1, col) not in visited:
        yield path + [(row + 1, col)], {*(visited - {(row, col)}), (row + 1, col)}

def path(board, end) -> list[tuple[int, int]]:
    path = []
    while end != (1, 1):
        path.insert(0, end)
        end = board[end]
    path.insert(0, (1, 1))
    return path

