def get_moves(grid: list[str], move: tuple[int, int]) -> list[tuple[int, int]]:
    res = []
    if (move[0] + 1, move[1]) in get_free_grid_cells(grid, move): 
        res.append((move[0] + 1, move[1]))
    if (move[0] - 1, move[1]) in get_free_grid_cells(grid, move):
        res.append((move[0] - 1, move[1]))
    if (move[0], move[1] + 1) in get_free_grid_cells(grid, move):
        res.append((move[0], move[1] + 1))
    if (move[0], move[1] - 1) in get_free_grid_cells(grid, move):
        res.append((move[0], move[1] - 1))
    return res

def is_inside_grid(grid: list[str], move: tuple[int, int]) -> bool:
    return (move[0] >= 0 and move[0] < len(grid) and
            move[1] >= 0 and move[1] < len(grid[0]))

def get_free_grid_cells(grid: list[str], move: tuple[int, int]) -> list[tuple[int, int]]:
    all_grid_cell_x = range(0, len(grid))
    all_grid_cell_y = range(0, len(grid[0]))
    all_grid_cells = []

    for x in all_grid_cell_x:
        for y in all_grid_cell_y:
            all_grid_cells.append((x, y))

    all_free_grid_cells = filter(
        lambda cell: grid[cell[0]][cell[1]] == '.', 
        all_grid_cells)
    all_free_grid_cells = list(all_free_grid_cells)
    return filter(lambda cell: cell != move, all_free_grid_cells)

