def dfs(grid: list[str], start: tuple[int, int], goal: tuple[int, int], max_depth: int = 200):
    x, y = start
    visited = [(x, y)]

    def open_options(r, c):
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            tr, tc = r + dr, c + dc
            if (
                0 <= tr < len(grid)
                and 0 <= tc < len(grid[0])
                and grid[tr] [tc] == '.'
                and (tr, tc) not in visited
                ):
                return [(tr, tc)]
        return []

    def backtrack(path):
        pr, pc = path[-1]
        options = open_options(pr, pc)
        if options == [] or path == []:
            return path
        for op in options:
            if op == goal:
                return path + [goal]
            if max_depth is not None:
                result = backtrack(path + [op], max_depth - 1)
            else:
                result = backtrack(path + [op])
                if result:
                    return result
            if result:
                return result
        return []

    return backtrack(visited)

