    if not (0 <= i < len(grid) and 0 <= j < len(grid[0])) or (i, j) in current_path or grid[i][j] == "#":
        return False
    current_path.append((i, j))

    if (i, j) == goal:
        return True

    if dfs(i+1, j, current_path.copy()):
        return True
    if dfs(i-1, j, current_path.copy()):
        return True
    if dfs(i, j+1, current_path.copy()):
        return True
    if dfs(i, j-1, current_path.copy()):
        return True

    return False

