    neighbors = []
    if pt[1] > 0 and grid[pt[0]][pt[1]-1] == '.':
        neighbors.append( (pt[0], pt[1]-1) )
    if pt[1] < len(grid[0])-1 and grid[pt[0]][pt[1]+1] == '.':
        neighbors.append( (pt[0], pt[1]+1) )
    if pt[0] > 0 and grid[pt[0]-1][pt[1]] == '.':
        neighbors.append( (pt[0]-1, pt[1]) )
    if pt[0] < len(grid)-1 and grid[pt[0]+1][pt[1]] == '.':
        neighbors.append( (pt[0]+1, pt[1]) )
    return neighbors


def shortestPath(path: list[tuple[int, int]], goal: tuple[int, int]) -> list[tuple[int, int]]:
    return [ pt for pt, _ in enumerate(reversed(path)) if path[pt][0] == goal[0] and goal[1] in { path[pt][1], path[pt-1][1] } ]


