class Node:
    def __init__(self, depth: int, visited: set[int]):
        self.depth = depth
        self.frontier = {s: depth}
        self.edges = edges
        self.visited = visited

    def solve(self) -> int:
        min_recursive = float('inf')
        new_nodes = [Node(self.depth + 1, {**self.visited, *list(map(lambda x: x[0], self.edges))})]
        for next_node in new_nodes:
            if next_node.frontier.get(t):
                if next_node.frontier.get(t) < min_recursive:
                    min_recursive = next_node.frontier.get(t)
                continue
            for e in filter(lambda e: next_node.visited.get(e[1], False) == False, next_node.edges):
                if next_node.frontier.get(e[1], float('inf')) > next_node.depth + e[2]:
                    next_node.frontier[e[1]] = next_node.depth + e[2]
                    next_node.visited[e[1]] = e[1]
            new_min_recursive = next_node.solve()
            if next_node.frontier.get(t):
                if next_node.frontier.get(t) < min_recursive:
                    min_recursive = next_node.frontier.get(t)
                continue
            if new_min_recursive < min_recursive:
                min_recursive = new_min_recursive
            new_nodes.append(next_node)
        return min_recursive
