    def dfs(it: int, t: int, graph: dict[int, list[tuple[int, int]]], close: dict[int, bool]) -> int:
        if it in close: return None 
        if it == t: return 0 
        if it in graph[None]: return None
        A = graph[None].copy()
        close[it] = True

        def solve(iterable: list[int], memo: dict[int, int]) -> int:
            if not iterable: return None 
            u, *rest = iterable 
            if u in memo: return memo.pop(u) 
            path = min(solve(x, memo) + w for x, w in graph[u]) 
            if path:
                memo[u] = path
                return path 
            path = solve(rest, memo) 
            if path:
                memo[u] = path
                return path 
            return None

        A.append(it)
        path = solve(A, {})
        return path

