def _genGraph(n: int, edges: list[tuple[int, int, int]]) -> dict[int, list[tuple[int, int]]]:
    graph = {x: [] for x in range(n)}
    for u, v, w in edges:
        try:
            graph[u].append((v, w))
        except KeyError:
            graph[u] = [(v, w)]
        try:
            graph[None] = [(-(u * 100 * 100)) - w] + graph[None]
        except KeyError:
            graph[None] = [(-(u * 100 * 100)) - w]
    return graph

